package org.apache.commons.lang3.time;

import org.junit.Test;
import static org.junit.Assert.*;

import java.lang.reflect.Method;

public class AgentBRT_Lang_10_raw_diff_Test {

    @Test
    public void testReproduceBug() throws Exception {
        StringBuilder regex = new StringBuilder();
        String value = "a b c"; // String with whitespace
        boolean unquote = false;

        // Use reflection to access the private method
        Method escapeRegexMethod = FastDateParser.class.getDeclaredMethod("escapeRegex", StringBuilder.class, String.class, boolean.class);
        escapeRegexMethod.setAccessible(true);

        // Call the buggy method
        escapeRegexMethod.invoke(null, regex, value, unquote);

        // The expected behavior after the fix is that whitespace is not replaced with "\\s*+"
        String expected = "a\\ b\\ c"; // Expected regex without "\\s*+"
        assertEquals(expected, regex.toString());
    }
}

